namespace RockPro{public static class LatchInProcess{
static JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=64000000};static IZSceneDoc Scene;static Dictionary<string,object> Pars;static Dictionary<string,IZElement> Nodes=new Dictionary<string,IZElement>();static Dictionary<string,Dictionary<string,object>> Specs=new Dictionary<string,Dictionary<string,object>>();
static Dictionary<string,object> O(object a){return(Dictionary<string,object>)a;}static double[] N(object a){return ((Array)a).Cast<object>().Select(Convert.ToDouble).ToArray();}static string E(string text,int depth){foreach(var k in Pars.Keys)text=System.Text.RegularExpressions.Regex.Replace(text,"\\b"+k+"\\b",m=>String.Concat(Enumerable.Repeat("Parent\\",depth))+"Params\\"+k);return text;}
static void Pose(IZSceneElement e,Dictionary<string,object> spec,int depth){var a=e.GetAnchorTransform();a.MakeIdentity();e.SetAnchorTransform(a);var m=e.GetTransformToParent();m.MakeIdentity();var r=(object[])spec["rotation"];var p=N(spec["initial"]);for(int i=0;i<3;i++){for(int j=0;j<3;j++)m.SetValue(i,j,Convert.ToDouble(((object[])r[i])[j]));m.SetValue(3,i,p[i]/1000);}e.SetTransformToParent(m);var ps=(object[])spec["position"];for(int i=0;i<3;i++)e.set_PositionTransformComponentExpression((eZTransformComponentType)i,E((string)ps[i],depth));e.ForceSetupParameterExpression();}
static List<IZElement> Children(IZElement e){var r=new List<IZElement>();if(e.Type!=eZElementType.Z_ELEMENT_ASSEMBLY)return r;var a=e.GetChildrenZArray();for(int i=0;i<e.GetChildrenCount();i++){object o;a.Get(i,out o);var c=(IZElement)o;if(c.Type==eZElementType.Z_ELEMENT_PART||c.Type==eZElementType.Z_ELEMENT_ASSEMBLY)r.Add(c);}return r;}
static IZElement Clone(IZElement src,IZAssembly parent){object copies=((IZSceneElement)src).CreateCopies(1,null);var array=(Array)copies;if(array.Length!=1)throw new Exception("Expected one catalog copy");var node=(IZElement)array.GetValue(0);try{parent.MoveChild(node,false);}catch{node.Remove();throw;}return node;}
static IZPart Box(Dictionary<string,object> spec){var dims=N(spec["dimensions_initial"]);var pr=Scene.CreateProfile();double[][] q={new[]{0.0,0.0},new[]{dims[0]/1000,0.0},new[]{dims[0]/1000,dims[1]/1000},new[]{0.0,dims[1]/1000}};for(int i=0;i<4;i++)pr.CreateLine(q[i],q[(i+1)%4],i+1);var part=Scene.CreatePart();var f=((IZPartFeatureMgr)part).CreateExtrudeFeature(eZOperationType.Z_UNITE,false,dims[2]/1000,0,0,pr,eZFeatureProfileRelType.Z_FEATURE_PROFILE_ABSORB);part.Update();var sb=(IZSizeBox)f;sb.Reset(false);var expr=(object[])spec["dimensions"];sb.LengthExpression=E((string)expr[0],2);sb.WidthExpression=E((string)expr[1],2);sb.HeightExpression=E((string)expr[2],2);((IZSceneElement)f).ForceSetupParameterExpression();part.SurfaceFinish.Color=0x808040;return part;}
static void Update(){((IZAssembly)Scene.GetTopElement()).RegenerateParts(true);Scene.Update();}
public static int Run(string folder){var result=new Dictionary<string,object>();IZDoc owned=null;bool passed=false;try{var req=O(J.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json"))));if((string)req["contract"]!="rockpro-t1-2023-unsaved-v1")throw new Exception("Wrong prototype contract");if(Convert.ToInt32(req["expected_pid"])!=System.Diagnostics.Process.GetCurrentProcess().Id)throw new Exception("Wrong PID");dynamic legacy=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)legacy.ZIronCADApp;if(!app.ApiVersion.StartsWith("25."))throw new Exception("Wrong host");var sources=new Dictionary<string,IZSceneDocUtility>();foreach(var x in O(req["sources"])){var doc=app.GetOpenDocByName((string)x.Value);if(doc==null)throw new Exception("Source not open: "+x.Key);sources[x.Key]=(IZSceneDocUtility)doc;}
 owned=app.OpenNewDoc(eZDocType.Z_SCENE,false,true,"");Scene=(IZSceneDoc)owned;Pars=O(req["parameters"]);foreach(var kv in Pars){var p=Scene.ParameterMgr.CreateParameter(eZParamType.Z_PARAMETER_TYPE_LENGTH,kv.Key,Convert.ToDouble(kv.Value)/1000);p.Expression=Convert.ToDouble(kv.Value).ToString(System.Globalization.CultureInfo.InvariantCulture)+" mm";}Nodes.Clear();Specs.Clear();var top=(IZAssembly)Scene.GetTopElement();int profiles=0,hardware=0,cuts=0;
 foreach(var x in (object[])req["parts"]){var s=O(x);string key=(string)s["key"];IZElement node;string kind=(string)s["kind"];if(kind=="box")node=(IZElement)Box(s);else if(kind=="profile"){var part=Scene.CreatePart();var f=(IZFeature)sources[(string)s["source"]].GetElementById(Convert.ToInt32(s["feature_id"]));var copy=f.CopyFeatureTo(part);var se=(IZSceneElement)copy;var id=se.GetTransformToParent();id.MakeIdentity();se.SetTransformToParent(id);var box=(IZSizeBox)copy;box.Reset(false);box.HeightExpression=E((string)s["length"],2);se.ForceSetupParameterExpression();part.Update();part.SurfaceFinish.Color=0xC0C0C0;node=(IZElement)part;profiles++;}else{var original=sources[(string)s["source"]].GetElementById(Convert.ToInt32(s["source_id"]));if(original.Name!=(string)s["source_name"])throw new Exception("Source identity mismatch "+key);node=Clone(original,top);hardware++;}node.Name="RockPro / "+key;Pose((IZSceneElement)node,s,1);Nodes[key]=node;Specs[key]=s;}
 foreach(var kv in Nodes)Pose((IZSceneElement)kv.Value,Specs[kv.Key],1);Update();foreach(var x in (object[])req["cuts"]){var c=O(x);var target=(IZPart)Nodes[(string)c["target"]];var src=(IZFeature)sources[(string)c["source"]].GetElementById(Convert.ToInt32(c["feature_id"]));if(src.OperationType!=eZOperationType.Z_SUBTRACT)throw new Exception("Negative template required");var f=src.CopyFeatureTo(target);((IZElement)f).Name="RockPro wyciecie / "+(string)c["key"];((IZExtrudeFeature)f).ExtrudeThroughPart=true;Pose((IZSceneElement)f,c,2);target.Regenerate();target.Update();cuts++;}Update();
 var checks=new List<object>();foreach(var x in (object[])req["check_cases"]){var c=O(x);foreach(var kv in O(c["parameters"]))Scene.ParameterMgr.GetParameterByName(kv.Key).Expression=Convert.ToDouble(kv.Value).ToString(System.Globalization.CultureInfo.InvariantCulture)+" mm";Update();foreach(var item in (object[])c["checks"]){var v=O(item);var node=Nodes[(string)v["key"]];if(v.ContainsKey("position")){var m=((IZSceneElement)node).GetTransformToParent();var p=N(v["position"]);for(int i=0;i<3;i++)if(Math.Abs(m.GetValue(3,i)*1000-p[i])>.02)throw new Exception("Position binding mismatch "+v["key"]+" axis="+i+" actual="+(m.GetValue(3,i)*1000)+" expected="+p[i]);}if(v.ContainsKey("dimensions")){var b=N(((IZPart)node).GetBody(true).GetBoundingBox());var d=N(v["dimensions"]);for(int i=0;i<3;i++)if(Math.Abs((b[i+3]-b[i])*1000-d[i])>.02)throw new Exception("Size binding mismatch "+v["key"]);}}checks.Add(c["name"]);}
 foreach(var node in Nodes.Values)node.SetDirtyFlag(eZDirtyFlag.Z_DIRTY_GRAPHICS);Scene.Update();try{Scene.UpdateGraphics(0);Scene.Redraw();result["graphics"]="PASS";}catch(Exception e){result["graphics_error"]=e.Message;}result["parts_top_level"]=Nodes.Count;result["profiles"]=profiles;result["catalog_occurrences"]=hardware;result["cutouts"]=cuts;result["parameter_checks"]=checks;result["api_version"]=app.ApiVersion;result["unsaved"]=owned.Modified;result["document_name"]=owned.Name;result["nodes"]=Nodes.ToDictionary(k=>k.Key,k=>k.Value.Id);passed=true;
 }catch(Exception e){result["error"]=e.ToString();}finally{if(!passed&&owned!=null&&Nodes.Count<72){try{owned.Close();}catch{}}result["passed"]=passed;File.WriteAllText(Path.Combine(folder,"result.json"),J.Serialize(result));}return passed?0:1;}
}}




